enum GameState {
    Menu,
    Playing,
    Paused,
    GameOver,
}

const allowedTransitions: Record<GameState, GameState[]> = {
    [GameState.Menu]: [GameState.Playing],
    [GameState.Playing]: [GameState.Paused, GameState.GameOver],
    [GameState.Paused]: [GameState.Playing, GameState.Menu],
    [GameState.GameOver]: [GameState.Menu],
}

function transition(from: GameState, to: GameState): string {
    const allowed = allowedTransitions[from].includes(to)
    return `${GameState[from]} → ${GameState[to]}: ${allowed ? "✓" : "✗ ruxsat yo'q"}`
}

console.log(transition(GameState.Menu, GameState.Playing))
console.log(transition(GameState.Playing, GameState.Paused))
console.log(transition(GameState.Menu, GameState.GameOver))

