const PaymentMethods = {
    cash: { label: "Naqd pul", icon: "💵", fee: 0 },
    card: { label: "Plastik karta", icon: "💳", fee: 0.01 },
    transfer: { label: "Bank o'tkazmasi", icon: "🏦", fee: 0.005 },
} as const

type PaymentMethod = keyof typeof PaymentMethods

function describePayment(method: PaymentMethod, amount: number): string {
    const info = PaymentMethods[method]
    const fee = Math.round(amount * info.fee)
    return `${info.icon} ${info.label}: ${amount} (komissiya ${fee})`
}

for (const method of Object.keys(PaymentMethods) as PaymentMethod[]) {
