enum Size3 { Small = "sm", Medium = "md", Large = "lg" }

function use1(s: Size1): string { return `union: ${s}` }
function use2(s: Size2): string { return `as const: ${s}` }
function use3(s: Size3): string { return `enum: ${s}` }

