type Currency = "UZS" | "USD" | "EUR"
const CURRENCIES = ["UZS", "USD", "EUR"] as const satisfies readonly Currency[]

function parseCurrency(s: string): Currency {
    const up = s.toUpperCase()
    if ((CURRENCIES as readonly string[]).includes(up)) return up as Currency
    throw new Error(`Noma'lum valyuta: ${s}`)
}

